const TK=k=>TEAM.find(x=>x.k===k)||TEAM[0];
/* capacidades: lista blanca. Sólo R2AVE puede escribir, y sólo el ajuste de inventario (apagado hasta que el administrador lo habilite) */
const CAPS=[
 {id:'inventory.stock.adjust',n:'Corregir stock (ajuste de inventario)',owner:'r2ave',perm:'edit_products',key:'adjust'},
 {id:'purchases.order.draft',n:'Preparar pedidos de compra',owner:'r2ave',future:true},
 {id:'promos.manage',n:'Gestionar promociones',owner:'r2ave',future:true},
 {id:'prices.change',n:'Modificar precios',owner:'r2ave',future:true},
 {id:'tasks.manage',n:'Administrar tareas',owner:'r2ave',future:true},
 {id:'ops.approve',n:'Aprobar operaciones',owner:'r2ave',future:true}];
const E=v=>typeof esc==='function'?esc(v):String(v);
const $m=c=>typeof money==='function'?money(c):String(c);
const nf=v=>String(Math.round((+v||0)*1000)/1000).replace('.',',');
const r2=()=>((S.cfg&&S.cfg.ci&&S.cfg.ci.r2)||{});
const isAdm=()=>typeof user!=='undefined'&&!!user&&user.role==='admin';
const seeTeam=()=>isAdm()||(typeof can==='function'&&can('staff'));
const nowT=()=>typeof now==='function'?now():Date.now();
const DAY=86400000;
/* ¿el asistente «a» puede usar la capacidad «id» con el usuario actual? (el permiso humano siempre limita) */
function capCheck(a,id){const c=CAPS.find(x=>x.id===id);if(!c)return{ok:false,why:'Esa acción no existe en el catálogo de R2AVE.'};
 if(c.owner!==a)return{ok:false,why:TK(a).n+' no tiene permiso para '+c.n.toLowerCase()+'. Sólo '+TK(c.owner).n+' puede hacerlo.'};
 if(c.future)return{ok:false,why:'«'+c.n+'» todavía no está habilitada: necesita la autorización del dueño, pruebas y auditoría.'};
 if(!r2()[c.key])return{ok:false,why:'El administrador no habilitó «'+c.n+'» para R2AVE (Equipo SVB R2AVE → Permisos de los asistentes).'};
 if(c.perm&&!(typeof can==='function'&&can(c.perm)))return{ok:false,why:'Tu usuario no tiene el permiso «'+((typeof PERMS!=='undefined'&&PERMS[c.perm])||c.perm)+'»: R2AVE no puede hacer por vos lo que vos no podés hacer.'};
 return{ok:true};}
CI.r2={TEAM,CAPS,capCheck};
const st=()=>{CI.st.asst=CI.st.asst||'r2ave';return CI.st;};

