function place(q,d){const M=CI.mapOf()||{items:[]};const MT=CI.MT;const z=M.items.filter(x=>MT[x.t]&&MT[x.t].zone);const L=[];
 const Q=typeof invQueryParse==='function'?invQueryParse(q):null;const F=Q&&typeof prodMatch==='function'?(S.products||[]).filter(p=>!p.archived&&prodMatch(p,Q)).slice(0,3):[];
 F.forEach(p=>{const g=M.items.find(x=>x.t==='gond'&&x.rubro===p.rubro);const r=(S.rubros||[]).find(x=>x.id===p.rubro);L.push('<b>'+E(p.name)+'</b>: '+(g?'en la góndola de '+E(g.label||(r&&r.name)||'su rubro'):'su rubro ('+E(r?r.name:'sin rubro')+') no tiene góndola en el plano')+'.');});
 if(!F.length){L.push(z.length?'El plano tiene '+z.length+' zonas: '+z.slice(0,10).map(x=>E(x.label||MT[x.t].n)).join(', ')+(z.length>10?'…':'')+'.':'El plano todavía no tiene zonas. Desde «Editar local» se puede cargar el plano de ejemplo SVB.');
  const po=(S.pOrders||[]).filter(o=>o.estado==='Solicitada');L.push(po.length?po.length+' pedido(s) de compra esperan recepción.':'No hay pedidos de compra esperando recepción.');
  L.push('Despacho: no hay pedidos de envío registrados en el sistema (la tienda con envíos sólo arma el WhatsApp).');}
 L.push('<span class="ci-mut" style="font-size:.8rem">Plano no calibrado: las medidas son aproximadas.</span>');
 return who('t2uluz','q')+li(L);}
/* V26.44 · respuestas de los seis especialistas: sólo leen datos reales del sistema */
function specAnswer(k,d){const L=[];const t0=nowT();const tk=d.tk;
 const today=(S.sales||[]).filter(x=>x.status==='ok'&&typeof dkey==='function'&&dkey(x.ts)===tk);const pm={};today.forEach(x=>(typeof salePays==='function'?salePays(x):[{m:x.method,a:x.total}]).forEach(p=>{pm[p.m]=(pm[p.m]||0)+(+p.a||0);}));
 const pmTxt=Object.keys(pm).length?Object.entries(pm).sort((a,b)=>b[1]-a[1]).map(([m,a])=>E(m)+' '+$m(a)).join(' · '):'sin ventas todavía';
 if(k==='vertice'){L.push('Ventas de hoy: <b>'+$m(d.tot)+'</b> en '+d.n+' venta(s)'+(d.n?' · ticket promedio '+$m(Math.round(d.tot/d.n)):'')+'.');
  L.push('Ayer: '+$m(d.totY)+' en '+d.nY+' venta(s).');
  const top=Object.entries(d.sold).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([id,q])=>{const p=(S.products||[]).find(x=>x.id===id);return p?E(p.name)+' ('+nf(q)+')':null;}).filter(Boolean);
  L.push(top.length?'Lo más vendido hoy: '+top.join(', ')+'.':'Todavía no hay productos vendidos hoy.');L.push('Medios de pago de hoy: '+pmTxt+'.');}
 else if(k==='nebula'){const cp=(S.coupons||[]).filter(c=>c.active&&(!c.to||c.to>=tk));const uses=(S.coupons||[]).reduce((a,c)=>a+((c.uses||[]).length),0);
  const soc=(S.customers||[]).filter(c=>c.status!=='baja'&&c.num).length;const mem=(S.members||[]).filter(m=>m.status==='activa'&&m.to>t0).length;
  L.push(cp.length+' cupón(es) activo(s)'+(cp.length?': '+cp.slice(0,4).map(c=>E(c.code)).join(', '):'')+' · '+uses+' uso(s) registrados.');
  L.push(soc+' socio(s) del Club · '+mem+' membresía(s) activa(s).');
  L.push('No envío promociones: el sistema no tiene WhatsApp Business ni correo conectados. Sólo se puede escribir a quien dio su permiso.');}
 else if(k==='quantum'){L.push(d.negAll.length+' producto(s) en negativo'+(d.negAll.length?': '+d.negAll.slice(0,5).map(p=>E(p.name)+' ('+nf(p.stock)+')').join(', '):'')+'.');
  L.push(d.lowAll.length+' con stock bajo (5 o menos)'+(d.lowAll.length?': '+d.lowAll.slice(0,5).map(p=>E(p.name)+' ('+nf(p.stock)+')').join(', '):'')+'.');
  L.push(nf(d.units)+' unidades en total · '+(S.pOrders||[]).filter(o=>o.estado==='Solicitada').length+' pedido(s) de compra por recibir.');
  L.push('Para corregir un conteo, pedíselo a R2AVE (es el único autorizado y sólo si el administrador lo habilitó).');}
 else if(k==='orion'){L.push(d.open.length?d.open.length+' caja(s) abierta(s).':'No hay cajas abiertas.');L.push('Ventas de hoy por medio de pago: '+pmTxt+'.');
  const fi=pm.fiado||0;L.push(fi?'A cuenta corriente hoy: '+$m(fi)+' (no entró a la caja).':'Hoy no hubo ventas a cuenta corriente.');
  L.push('No muevo dinero ni abro o cierro cajas: eso lo hace una persona con permiso.');}
 else if(k==='atenea'){if(!seeTeam())return who('atenea','n')+'Tu usuario no tiene permiso de personal: no puedo mostrarte datos del equipo.';
  const em=(S.employees||[]).filter(e=>e.active);const ps=(S.punches||[]).filter(p=>typeof dkey==='function'&&dkey(p.ts)===tk);
  const pres=em.filter(e=>{const l=ps.filter(p=>p.empId===e.id).sort((a,b)=>a.ts-b.ts).pop();return l&&l.kind==='in';});
  L.push(em.length+' persona(s) activa(s) en el personal · '+ps.length+' fichada(s) hoy.');L.push(pres.length?'Trabajando ahora: '+pres.map(e=>E(e.name)).join(', ')+'.':'Nadie tiene una entrada abierta ahora.');}
 else if(k==='nexus'){const au=(S.audit||[]).length;const cloud=typeof CLOUD_URL!=='undefined'&&!!CLOUD_URL;
  L.push(au+' registro(s) de auditoría encadenados en este equipo.');L.push(cloud?'Nube configurada: los datos se sincronizan con el servidor.':'Nube sin configurar: este equipo guarda todo en el navegador.');
  L.push('El equipo responde con reglas locales sobre tus datos: no hay un modelo de IA externo conectado.');}
 return who(k,'q')+li(L);}
const SPECK=['vertice','nebula','quantum','orion','atenea','nexus'];
function preAnswer(q){if(CI._inPre)return null;const t=fold(q);let a=st().asst;
 TEAM.forEach(x=>{if(t.includes(fold(x.n))||t.includes(x.k))a=x.k;});
 if(/segunda opinion|que opinas|opinion de/.test(t))a='s2hakira';
 const d=CI.data();
 if(/(corregi|corregir|correccion|ajust|conte|recont)/.test(t)&&/(stock|inventario|unidades|conteo|fisic)/.test(t)){
  const c=capCheck(a,'inventory.stock.adjust');
  if(!c.ok){if(typeof audit==='function')audit('R2AVE_RECHAZO','inventory.stock.adjust · asistente '+TK(a).n+' · '+c.why.slice(0,160));return who(a,'n')+E(c.why);}
  setTimeout(()=>CI.r2.adjust(q),30);return who('r2ave','p')+'Abrí la corrección de stock: elegí el artículo, contá lo que hay físicamente, escribí el motivo y confirmá. No cambio nada hasta que confirmes.';}
 if(SPECK.includes(a))return specAnswer(a,d);
 if(a==='s2hakira')return second(d);
 if(a==='m2argoth'||/riesgo|alerta|anomal/.test(t))return risks(d);
 if(a==='t2uluz'||/(donde|ubicaci|zona|mapa|recepci|despach|deposito)/.test(t))return place(q,d);
 CI._inPre=true;try{return who('r2ave','q')+CI.answer(q);}finally{CI._inPre=false;}}
