 P('columna',ox+base.W/2,oy-0.2,0.4,0.4,'Columna');P('puerta',ox+tw-1.1,3.25,2.2,0.15,'Acceso al depósito');P('puerta',2.2,D-0.15,1.4,0.15,'Acceso del personal');
